import { MakeLogicType, actions, afterMount, connect, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { llmAnalyticsEvaluationReportsRunsList } from '../../generated/api'
import type { EvaluationReportRunApi } from '../../generated/api.schemas'
import { loadReportsForEvaluation, requireCurrentTeamId } from '../evaluationReportLogic'
import type { EvaluationReportRun } from '../types'

export interface EvaluationLatestReportRunLogicProps {
    evaluationId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface evaluationLatestReportRunLogicValues {
    currentTeamId: number | null // teamLogic
    latestRun: EvaluationReportRun | null
    latestRunLoadFailed: boolean
    latestRunLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface evaluationLatestReportRunLogicActions {
    loadLatestRun: (_: void) => void
    loadLatestRunFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadLatestRunSuccess: (
        latestRun: EvaluationReportRunApi | null,
        payload?: void
    ) => {
        latestRun: EvaluationReportRunApi | null
        payload?: void
    }
    setLatestRunLoadFailed: (failed: boolean) => {
        failed: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface evaluationLatestReportRunLogicMeta {
    key: string
}

export type evaluationLatestReportRunLogicType = MakeLogicType<
    evaluationLatestReportRunLogicValues,
    evaluationLatestReportRunLogicActions,
    EvaluationLatestReportRunLogicProps,
    evaluationLatestReportRunLogicMeta
>

/** Only the newest report of an evaluation, for previews that don't need the history or the report settings. */
export const evaluationLatestReportRunLogic = kea<evaluationLatestReportRunLogicType>([
    path((key) => ['products', 'ai_observability', 'frontend', 'evaluations', 'evaluationLatestReportRunLogic', key]),
    props({} as EvaluationLatestReportRunLogicProps),
    key((props) => props.evaluationId),
    connect(() => ({ values: [teamLogic, ['currentTeamId']] })),
    actions({
        setLatestRunLoadFailed: (failed: boolean) => ({ failed }),
    }),
    loaders(({ actions, props, values }) => ({
        latestRun: [
            null as EvaluationReportRun | null,
            {
                loadLatestRun: async (_: void, breakpoint) => {
                    const teamId = requireCurrentTeamId(values.currentTeamId)
                    try {
                        const report = (await loadReportsForEvaluation(teamId, props.evaluationId)).find(
                            (candidate) => !candidate.deleted
                        )
                        const response = report
                            ? await llmAnalyticsEvaluationReportsRunsList(teamId.toString(), report.id, { limit: 1 })
                            : null
                        actions.setLatestRunLoadFailed(false)
                        return response?.results?.[0] ?? null
                    } catch {
                        // The card shows its own retry, so a failure doesn't also raise the global toast.
                        breakpoint()
                        actions.setLatestRunLoadFailed(true)
                        return values.latestRun
                    }
                },
            },
        ],
    })),
    reducers({
        // Stays set through a retry, so the card keeps its error and button while the request runs.
        latestRunLoadFailed: [
            false,
            {
                setLatestRunLoadFailed: (_, { failed }) => failed,
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadLatestRun()
    }),
])
